// The guard's decision (hooks/guard.mjs is the hook around it). A file flowapi generated is
// changed through flowapi-sdk.yml and a new `generate`, never by hand, so an edit of one is
// refused with that hint. The generated files are the ones listed in the nearest
// .flowapi/lock.json above the target (docs/lock.md).
//
// Two clients ask, each with its own event: Claude Code names the file in its native tool input
// (`decide`), an Agent Plugins core client in the `file.modify` tool profile (`decideCore`, core
// 1.1.0 §7.3.6). Both end in the same decision for each path.
//
// It fails open: a missing, unreadable or broken lock, or an event it does not understand, and
// the edit goes through. `flowapi generate` still finds a hand edit later by its hash.

import { readFileSync } from 'node:fs'
import nodePath from 'node:path'

export const LOCK_DIR = '.flowapi'
export const LOCK_FILE = 'lock.json'
/** Where the person's own code lives: listed or not, these stay editable. */
export const CUSTOM_ZONES = ['src/lib/', 'examples/']
/** Claude Code's tools that write one file, named by `file_path` or `notebook_path`. */
export const EDIT_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit'])

const CHANGE_CONFIG =
  'change flowapi-sdk.yml and run generate again; your own code goes in src/lib/ or examples/.'

/**
 * The decision for one Claude Code PreToolUse event: `{ reason }` to deny, null to stay silent.
 * `path`, `readFile` and `platform` are injected so tests can run the Windows rules on any machine.
 */
export function decide(event, options = {}) {
  if (!event || !EDIT_TOOLS.has(event.tool_name)) return null
  const input = event.tool_input ?? {}
  return decidePaths([input.file_path ?? input.notebook_path], event.cwd, options)
}

/**
 * The decision for one core PreToolUse event. Only the `file.modify` profile names files in a
 * portable way; every path an operation touches is checked: an edit, a write and a delete of a
 * generated file, and a move from or onto one, are all refused. Without that profile: silent.
 */
export function decideCore(event, options = {}) {
  const profile = event?.tool_profile
  if (!profile || profile.name !== 'file.modify') return null
  const operations = profile.input?.operations
  if (!Array.isArray(operations)) return null
  const paths = operations.flatMap((op) => (op?.kind === 'move' ? [op.from, op.to] : [op?.path]))
  return decidePaths(paths, event.cwd, options)
}

/** The first refusal among `paths`, each resolved against `cwd`; null when none is refused. */
function decidePaths(paths, cwd, options) {
  for (const target of paths) {
    if (typeof target !== 'string' || target === '') continue
    const decision = decidePath(target, cwd, options)
    if (decision) return decision
  }
  return null
}

function decidePath(target, cwd, options) {
  const { path = nodePath, readFile = readFileSync, platform = process.platform } = options
  const fold = platform === 'win32' || platform === 'darwin' // case-insensitive file systems
  const same = (a, b) => (fold ? a.toLowerCase() === b.toLowerCase() : a === b)
  const full = path.resolve(cwd || process.cwd(), target)

  const parent = path.dirname(full)
  if (same(path.basename(full), LOCK_FILE) && same(path.basename(parent), LOCK_DIR)) {
    return {
      reason: `${LOCK_DIR}/${LOCK_FILE} is written by flowapi generate alone: ${CHANGE_CONFIG}`,
    }
  }

  let found = null
  try {
    found = nearestLock(parent, path, readFile)
  } catch {
    return null // a lock that cannot be read or parsed blocks nothing
  }
  if (!found) return null
  const files = found.lock?.files
  if (!files || typeof files !== 'object' || Array.isArray(files)) return null

  const rel = path.relative(found.root, full).split(path.sep).join('/')
  if (rel === '' || rel.startsWith('../')) return null
  const key = fold ? rel.toLowerCase() : rel
  if (CUSTOM_ZONES.some((zone) => key.startsWith(fold ? zone.toLowerCase() : zone))) return null
  const listed = Object.keys(files).some((name) => same(name, rel))
  if (!listed) return null
  return {
    reason: `${rel} is generated by flowapi from flowapi-sdk.yml (listed in ${LOCK_DIR}/${LOCK_FILE}); do not edit it by hand: ${CHANGE_CONFIG}`,
  }
}

/**
 * The nearest directory at or above `dir` that holds the lock, with the lock parsed.
 * Null when there is none; throws when one exists but cannot be read or parsed.
 */
export function nearestLock(dir, path = nodePath, readFile = readFileSync) {
  for (let current = dir; ; current = path.dirname(current)) {
    let text = null
    try {
      text = readFile(path.join(current, LOCK_DIR, LOCK_FILE), 'utf8')
    } catch (error) {
      if (error?.code !== 'ENOENT' && error?.code !== 'ENOTDIR') throw error
    }
    if (text !== null) return { root: current, lock: JSON.parse(text) }
    if (path.dirname(current) === current) return null
  }
}
